r = this.color;\n        if (Date.now() - this.lastHitTime < this.hitFlashDuration) { drawColor = { r: 255, g: 255, b: 255 }; }\n        \n        const cHex = (drawColor.r << 16) + (drawColor.g << 8) + drawColor.b;\n        this.gfx.beginFill(cHex, 1);\n\n        if (this.type === '"'"'purple'"'"') {\n            this.gfx.drawPolygon([-this.width\/2, -this.height\/2, this.width\/2, -this.height\/2, this.width*0.4, -this.height*0.1, this.width\/2, this.height\/2, -this.width\/2, this.height\/2, -this.width*0.4, this.height*0.1]);\n        } else if (this.type === '"'"'orange'"'"') {\n            const points = [];\n            for (let i = 0; i < 5; i++) {\n                points.push(this.width\/2 * Math.cos((Math.PI*2\/5) * i - Math.PI\/2), this.height\/2 * Math.sin((Math.PI*2\/5) * i - Math.PI\/2));\n            }\n            this.gfx.drawPolygon(points);\n        } else if (this.type === '"'"'green'"'"') {\n            this.gfx.drawPolygon([0, -this.height\/2, this.width\/2, this.height\/2, -this.width\/2, this.height\/2]);\n        } else { \n            this.gfx.drawRoundedRect(-this.width\/2, -this.height\/2, this.width, this.height, this.width * 0.2);\n        }\n        this.gfx.endFill();\n\n        const fHex = (this.faceColor.r << 16) + (this.faceColor.g << 8) + this.faceColor.b;\n        this.gfx.beginFill(fHex, 1);\n        this.gfx.drawCircle(0, -this.height * 0.15, this.width \/ 8);\n        this.gfx.endFill();\n\n        this.gfx.beginFill(0xFFFFFF, 0.7);\n        this.gfx.drawCircle(0, -this.height * 0.15, this.width \/ 12);\n        this.gfx.endFill();\n\n        if (this.health > 0 && this.health < this.initialHealth) {\n            const hBW = this.width * 0.8;\n            const hBH = 4;\n            const hP = Math.max(0, Math.min(1, this.health \/ this.initialHealth));\n            const healthPercentage = (this.health \/ this.initialHealth) * 100;\n\n            const barX = -this.width * 0.4;\n            const barY = -this.height\/2 - hBH